//! Replays the scripted sessions of `fixtures/enchant_anvil/{enchant,anvil,grindstone}.txt.gz` (generated by
//! `oracle/EnchantAnvilOracle.java` through the REAL vanilla `EnchantmentMenu`/`AnvilMenu`/`GrindstoneMenu` of a real
//! `ServerPlayer` on a real `ServerLevel`; regenerate with `scripts/enchant-anvil-golden.sh`) on our menus, with a
//! `ServerLevel` of the same blocks, and compares every state line and container packet after every operation.
//! The replay machinery is `common::menu_oracle`.

use crate::common::menu_oracle::replay;

fn replay_section(section: &str) {
    let ops = replay("enchant_anvil", section);
    assert!(ops > 100, "fixture has {ops} ops");
}

#[test]
fn enchantment_menu_golden() {
    replay_section("enchant");
}

#[test]
fn anvil_menu_golden() {
    replay_section("anvil");
}

#[test]
fn grindstone_menu_golden() {
    replay_section("grindstone");
}
